import {detectChatLanguage,chatText} from './i18n.js';
import {E,money,icon,button,link,field,select,textarea,checkbox,table,badge,heading,notice} from './ui.js';
import {colours,colour,available,productImage,normalizePhone} from './core.js';
import {can,requirePermission,permissionSet} from './access.js';

export const channels=['Website','WhatsApp','Messenger'];
export const themes={Sage:{accent:'#466b5c',surface:'#f2f5ef'},Graphite:{accent:'#202630',surface:'#f1f3f6'},Navy:{accent:'#233e67',surface:'#edf2f9'},Forest:{accent:'#275745',surface:'#edf4f0'},Burgundy:{accent:'#6e3347',surface:'#f6eef1'}};
export const supportModule=channel=>'support-'+channel.toLowerCase();
export function canChat(s,channel,action='view'){return can(s,'support',action)&&can(s,supportModule(channel),action);}
export function eligibleStaff(s,channel){return s.records.staff.filter(p=>p.status==='Active'&&!p.archived&&canChat({...s,previewStaff:p.id,previewRole:p.role},channel,'edit'));}
export function currentStaff(s){return s.previewStaff?s.records.staff.find(p=>p.id===s.previewStaff):s.records.staff.find(p=>p.role===(s.previewRole||'Super Admin')&&p.status==='Active');}
export function initEngagement(s){
  s.support??={enabled:true,channels:{Website:true,WhatsApp:true,Messenger:true},conversations:[
    {id:'CHAT-001',channel:'WhatsApp',customer:'Sample WhatsApp customer',mode:'human',status:'Waiting',assignee:null,messages:[{role:'customer',text:'I need help choosing a shoe size.'}],sample:true},
    {id:'CHAT-002',channel:'Messenger',customer:'Sample Messenger customer',mode:'human',status:'Waiting',assignee:null,messages:[{role:'customer',text:'Can someone help me with a return?'}],sample:true}
  ]};
}
export function catalogueMatches(s,q){const text=q.toLowerCase().trim();const tokens=text.split(/\s+/).filter(Boolean);return s.products.filter(p=>p.status==='Active'&&!p.archived&&(!text||tokens.every(t=>(p.name+' '+p.category+' '+colours(p).map(c=>c.name).join(' ')).toLowerCase().includes(t))));}
export function searchResults(s,q){const matches=catalogueMatches(s,q).slice(0,5);return `${q?`<p class="search-caption">${matches.length?'Matching pieces':'No matching pieces'}</p>`:'<p class="search-caption">Explore the collection</p>'}${matches.map(p=>`<a href="#/product/${p.id}" class="search-result" data-search-result><img src="${E(productImage(p))}" alt=""><span><strong>${E(p.name)}</strong><small>${E(p.category)}</small></span><strong>${money(p.price)}</strong></a>`).join('')}${!matches.length?'<p class="muted small">Try a product, category or colour.</p>':''}<div class="search-categories">${['Shoes','Bags','Wallets','Socks','Belts'].map(c=>link(c,'/shop?category='+c,'category-pill')).join('')}</div>`;}
export function searchPanel(s){return `<div class="search-shade" style="--search-top:${Number(s.searchTop)||124}px" data-action="close-search" ${s.searchOpen?'':'hidden'}></div><section style="--search-top:${Number(s.searchTop)||124}px" class="header-search ${s.searchOpen?'is-open':''}" id="header-search" aria-label="Search products" ${s.searchOpen?'':'hidden'}><div class="search-panel-head"><h2>What are you looking for?</h2>${button(icon('close'),'close-search','aria-label="Close search"','icon-btn')}</div><form data-form="search" class="search-input-row">${icon('search')}<input type="search" name="q" id="header-query" autocomplete="off" placeholder="Product, category or colour…" value="${E(s.headerQuery||'')}" aria-label="Search products"><button class="btn small">Search</button></form><div id="header-search-results">${searchResults(s,s.headerQuery||'')}</div></section>`;}
export function themeSettings(s){const v=s.saved['settings-theme']||themes.Sage;return `<h3>Main theme colours</h3><p class="small muted mb">Choose a preset or set your own accent and workspace colours. Your accent colour applies to both the storefront and Admin.</p><div class="theme-presets">${Object.entries(themes).map(([name,t])=>button(`<span style="background:${t.accent}"></span>${name}`,'theme-preset',`data-value="${name}"`,'theme-choice')).join('')}</div><div class="field-grid mt">${field('Primary accent','accent',v.accent,'color','required')}${field('Workspace background','surface',v.surface,'color','required')}</div><div class="theme-sample" style="--sample-accent:${v.accent};--sample-bg:${v.surface}"><strong>AELVO Admin</strong><span class="sample-button">Primary action</span></div>${notice('Text contrast is calculated from your selected colours. Theme changes apply to the storefront and Admin in this session.')}`;}
export function applyTheme(s){const v=s.saved['settings-theme']||themes.Sage;const light=hex=>{const n=hex.slice(1).match(/../g).map(h=>parseInt(h,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);const lum=n[0]*.2126+n[1]*.7152+n[2]*.0722;return (lum+.05)/.05>1.05/(lum+.05)?'#111111':'#ffffff';};if(!/^#[0-9a-f]{6}$/i.test(v.accent)||!/^#[0-9a-f]{6}$/i.test(v.surface))return;const mix=(a,b,t)=>'#'+a.slice(1).match(/../g).map((h,i)=>Math.round(parseInt(h,16)*(1-t)+parseInt(b.slice(1+i*2,3+i*2),16)*t).toString(16).padStart(2,'0')).join('');const tint=mix(v.accent,'#faf9f5',.86),border=mix(v.accent,'#faf9f5',.7),canvas=mix(v.accent,'#faf9f5',.97);const root=document.documentElement?.style;if(root){root.setProperty('--site-tint',tint);root.setProperty('--site-on-tint',light(tint));root.setProperty('--site-border',border);root.setProperty('--site-canvas',canvas);root.setProperty('--site-accent',v.accent);root.setProperty('--site-on-accent',light(v.accent));root.setProperty('--site-soft',v.surface);root.setProperty('--site-on-soft',light(v.surface));root.setProperty('--admin-accent',v.accent);root.setProperty('--admin-on-accent',light(v.accent));root.setProperty('--admin-surface',v.surface);root.setProperty('--admin-on-surface',light(v.surface));}}
export function loginSettings(s){const v=s.saved['settings-login']||{};return `<h3>Social account creation</h3><p class="small muted mb">Customers can create an account with Google or Facebook after the server connections are configured. A verified mobile number is still required for phone-dependent checkout.</p>${['Google','Facebook'].map(provider=>`<div class="integration-box"><div class="between"><h3>${provider}</h3>${badge('Not connected','outline')}</div>${checkbox('Show '+provider+' on sign-in and signup',provider.toLowerCase(),v[provider.toLowerCase()]??true)}${field(provider==='Google'?'Google client ID':'Facebook App ID',provider.toLowerCase()+'Id',v[provider.toLowerCase()+'Id']||'')}${field('Client secret','secret','','password','disabled placeholder="Configure securely on the server"')}</div>`).join('')}${notice('These settings control the planned login buttons. They do not create OAuth sessions or verify an account in this frontend.')}`;}
export function socialButtons(s){const v=s.saved['settings-login']||{};return `<div class="social-signin">${(v.google??true)?button('<span class="social-letter">G</span>Continue with Google','social-login','data-provider="Google"','btn secondary full'):''}${(v.facebook??true)?button('<span class="social-letter">f</span>Continue with Facebook','social-login','data-provider="Facebook"','btn secondary full'):''}</div>`;}
export function aiSettings(s){const v=s.saved['settings-assistant']||{};return `<h3>AELVO Assistant & support routing</h3>${notice('Workflow preview only. A live AI model, WhatsApp Business and Messenger are not connected.')}<div class="mt">${checkbox('Show the website assistant','enabled',s.support.enabled)}</div><div class="integration-box"><h3>Channels</h3>${channels.map(c=>checkbox(c,'channel'+c,s.support.channels[c])).join('')}<p class="form-help">WhatsApp and Messenger messages will enter this inbox after backend/webhook setup.</p></div>${select('Human handoff','routing',['Admin + permissioned staff'],'Admin + permissioned staff')}${textarea('Approved support guidance','guidance',v.guidance||'Use current catalogue, stock, verified order data and approved policies. Ask the customer to confirm checkout. Escalate uncertainty and refund requests to the support team.')}${field('Facebook Page ID','pageId',v.pageId||'')}${field('WhatsApp business phone ID','phoneId',v.phoneId||'')}${field('AI / Meta credentials','secret','','password','disabled placeholder="Server secrets only — not collected here"')}${notice('Grant Support inbox and the relevant channel permissions under Team & Access. Handoff pauses automated replies until an authorized agent resumes assistance.')}`;}
function conversation(s){initEngagement(s);return s.support.conversations.find(c=>c.id===s.websiteConversation);}
export function newWebsiteConversation(s){initEngagement(s);const c={id:'WEB-'+Date.now(),channel:'Website',customer:s.user?.name||'Website visitor',mode:'assistant',status:'Open',assignee:null,language:s.language||'en',messages:[{role:'assistant',text:chatText({language:s.language||'en'},'welcome')}],sample:true};s.support.conversations.push(c);s.websiteConversation=c.id;return c;}
export function handoff(s,c){c.mode='human';c.status='Waiting';c.assignee=null;const agents=eligibleStaff(s,c.channel);c.messages.push({role:'system',text:chatText(c,agents.length?'handoff':'waiting')});}
function catalogueReply(s,c,text){const t=text.toLowerCase(),category=/shoe|sneaker|জুতা|juta/.test(t)?'Shoes':/bag|ব্যাগ/.test(t)?'Bags':/wallet|মানিব্যাগ/.test(t)?'Wallets':null;const priceMatch=t.match(/(?:under|within|budget|below|মধ্যে|বাজেট)\s*[৳টাকাtkbdt]*\s*(\d+)/i),max=priceMatch?Number(priceMatch[1]):Infinity;const list=s.products.filter(p=>p.status==='Active'&&!p.archived&&p.variants.some(v=>available(p,v.size,v.color)>0)&&(!category||p.category===category)&&p.price<=max);c.suggestions=list.map(p=>p.id);c.messages.push({role:'assistant',text:chatText(c,list.length?'choose':'empty')});}
export function receiveCustomerMessage(s,text){const c=conversation(s)||newWebsiteConversation(s);if(!text.trim())return c;c.language=detectChatLanguage(text,c.language||s.language||'en');c.messages.push({role:'customer',text:text.trim()});if(c.mode==='human'){if(c.status==='Resolved')c.status='Waiting';return c;}const t=text.toLowerCase();if(/payment|pay|checkout|পেমেন্ট|পেমেন|টাকা দেব|taka dibo|bkash|bKash|বিকাশ/i.test(t)){c.messages.push({role:'assistant',text:chatText(c,'payment')});return c;}if(/human|agent|staff|admin|মানুষ|সাপোর্ট|মানুষের|kotha bol|manush/.test(t)){handoff(s,c);return c;}if(/track|status|order.*(?:koi|kothay)|অর্ডার.*(?:কোথা|অবস্থা)/.test(t)){if(!s.user?.verified)c.messages.push({role:'assistant',text:chatText(c,'private')});else{const orders=s.orders.filter(o=>!o.archived&&(o.customerId?s.user.id&&o.customerId===s.user.id:normalizePhone(o.phone)===normalizePhone(s.user.phone)));c.messages.push({role:'assistant',text:orders.length?orders.map(o=>o.id+': '+o.status).join('\n'):chatText(c,'noOrders')});}return c;}if(/return|refund|ফেরত|রিফান্ড/.test(t)){c.messages.push({role:'assistant',text:chatText(c,'refund')});handoff(s,c);return c;}if(/delivery|shipping|ডেলিভারি/.test(t)){c.messages.push({role:'assistant',text:chatText(c,'delivery')});return c;}if(/product|shoe|sneaker|bag|wallet|shop|order|জুতা|ব্যাগ|পণ্য|অর্ডার|juta|kinte|কিন|browse|show|hello|hi|দেখ/.test(t)){catalogueReply(s,c,text);return c;}c.messages.push({role:'assistant',text:chatText(c,'fallback')});handoff(s,c);return c;}
export function assistantWidget(s){initEngagement(s);if(!s.support.enabled||!s.support.channels.Website)return '';const c=conversation(s);return `${button(icon('users')+'<span>Ask AELVO</span>','assistant-open','aria-label="Open AELVO assistant"','assistant-launcher')}<section class="assistant-panel ${s.assistantOpen?'open':''}" aria-label="AELVO support" ${s.assistantOpen?'':'hidden'}><header><div><strong>AELVO Assistant</strong><small>Preview · Live AI not connected</small></div>${button(icon('close'),'assistant-close','aria-label="Close assistant"','icon-btn')}</header><div class="assistant-messages" id="assistant-messages">${(c?.messages||[]).map(m=>`<div class="chat-message ${m.role}"><small>${m.role==='customer'?'You':m.role==='staff'?E(m.author||'Support team'):m.role==='system'?'Support update':'Catalogue helper'}</small><p>${E(m.text).replaceAll('\n','<br>')}</p></div>`).join('')}${c?.suggestions?.map(id=>{const p=s.products.find(p=>p.id===id);return p?`<div class="chat-product"><img src="${E(productImage(p))}" alt="${E(p.name)}"><div><strong>${E(p.name)}</strong><p>${money(p.price)}</p>${p.variants.some(v=>available(p,v.size,v.color)>0)?button('Choose colour & size','assistant-product',`data-id="${p.id}"`,'btn small secondary'):'<p class="small muted">Currently unavailable</p>'}</div></div>`:'';}).join('')||''}</div><div class="assistant-shortcuts">${button('Browse products','assistant-prompt','data-text="Show products"','text-link')}${button('Talk to the team','assistant-handoff','','text-link')}${link('Review bag & checkout','/cart','text-link')}</div><form data-form="assistant-message" class="assistant-compose"><input name="message" required maxlength="2000" autocomplete="off" placeholder="Write your message…" aria-label="Message AELVO"><button class="btn small">Send</button></form><p class="assistant-foot">No real messages or orders are sent from this preview.</p></section>`;}
export function inbox(s,id){initEngagement(s);const rows=s.support.conversations.filter(c=>canChat(s,c.channel)&&!c.archived);let c=rows.find(c=>c.id===id);if(id&&!c)return notice('This conversation is unavailable or outside your channel permissions.');const staff=currentStaff(s);return `${heading('Support Inbox','Website, WhatsApp and Messenger handoffs.',link('AI & channels','/admin/settings/assistant','btn secondary'))}${notice('Sample conversations. Live AI, Meta channels and external replies are not connected.')}<div class="inbox-layout mt"><aside class="card inbox-list">${rows.length?rows.map(r=>link(`<span>${badge(r.channel)} ${badge(r.status,'outline')}</span><strong>${E(r.customer)}</strong><small>${E(r.messages.at(-1)?.text.slice(0,90)||'')}</small>`,'/admin/support/'+r.id,c?.id===r.id?'selected':'')).join(''):'<p>No conversations in your permitted channels.</p>'}</aside><div>${c?`<div class="card"><div class="between"><div><h3>${E(c.customer)}</h3><p class="small muted">${E(c.id)} · ${E(c.channel)} · ${E(c.mode==='human'?'Human support':'Assistant mode')}</p></div>${badge(c.assignee?s.records.staff.find(p=>p.id===c.assignee)?.name||'Assigned':'Unassigned')}</div><div class="support-messages">${c.messages.map(m=>`<div class="chat-message ${m.role}"><small>${E(m.author||m.role)}</small><p>${E(m.text).replaceAll('\n','<br>')}</p></div>`).join('')}</div>${canChat(s,c.channel,'edit')?`<div class="flex support-actions">${button('Take conversation','support-take',`data-id="${c.id}"`,'btn small secondary')}${button('Resolve','support-resolve',`data-id="${c.id}"`,'btn small secondary')}${button('Resume assistant','support-resume',`data-id="${c.id}"`,'btn small secondary')}</div><form data-form="support-reply" data-id="${c.id}" class="mt">${textarea('Reply','message','','required maxlength="2000"')}<div class="error-text" data-error></div><button class="btn" ${c.assignee!==staff?.id?'disabled':''}>Send preview reply</button></form><form data-form="support-assign" data-id="${c.id}" class="mt">${select('Assign to authorized staff','staff',eligibleStaff(s,c.channel).map(p=>[p.id,p.name]),c.assignee||'')}<div class="error-text" data-error></div><button class="btn small secondary">Assign conversation</button></form>`:notice('View permission only. Replying requires Support inbox and channel Edit permission.')}</div>`:notice('Select a conversation to read the thread or take over from the assistant.')}</div></div>`;}
export function supportRecord(s,id){const c=s.support.conversations.find(x=>x.id===id);if(!c||!canChat(s,c.channel,'edit'))throw Error('You do not have permission to handle this channel.');return c;}
export function assertAssignee(s,c){if(c.assignee!==currentStaff(s)?.id)throw Error('Take or assign the conversation before replying.');}
